// The shapes the pieces of the Tasks screen pass between them.
//
// `components["schemas"]["TaskRead"]` is the server's own description of a task
// (src/api/schema.ts, regenerated by `npm run gen:api`), so a field renamed or retyped on
// the server is a type error in the screen that reads it instead of a blank value on the
// page. A row this screen has just added carries a local id until the server answers with
// the task's own, which is why `id` is nothing more special than a string.
import type { components } from "@/api/schema";

export type Task = components["schemas"]["TaskRead"];

/** What useSharedTasks hands the screen: the shared list, and every change to it. */
export type SharedTasks = {
  tasks: Task[];
  loading: boolean;
  loadFailed: boolean;
  /** The task added last, so its row can be shown arriving; null until one is added. */
  freshId: string | null;
  /** When the server last confirmed a read or a write, as an ISO date-time. */
  syncedAt: string | null;
  /** What the server refused, in the words the visitor is shown; empty when all is well. */
  syncError: string;
  addTask: (title: string) => void;
  setDone: (task: Task, done: boolean) => void;
  removeTask: (task: Task) => void;
};
